import{_ as o,o as t,c as d,a2 as c}from"./chunks/framework.C66fElYV.js";const h=JSON.parse('{"title":"Java aifei v1.0.4 → v1.1.0+ 演进同步评估","description":"","frontmatter":{},"headers":[],"relativePath":"arch/java-v1.1.0-sync.md","filePath":"arch/java-v1.1.0-sync.md","lastUpdated":1787462644000}'),a={name:"arch/java-v1.1.0-sync.md"};function r(i,e,n,s,l,g){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="java-aifei-v1-0-4-→-v1-1-0-演进同步评估" tabindex="-1">Java aifei v1.0.4 → v1.1.0+ 演进同步评估 <a class="header-anchor" href="#java-aifei-v1-0-4-→-v1-1-0-演进同步评估" aria-label="Permalink to &quot;Java aifei v1.0.4 → v1.1.0+ 演进同步评估&quot;">​</a></h1><blockquote><p><strong>核对日期</strong>：2026-08-22 <strong>2026-08-23 拍板</strong>：P0-2 时间转换采用方案 B —— <code>ToTime</code>/<code>GetTime</code> 直接改签名返回 <code>(time.Time, error)</code>（放弃 <code>ToTimeE</code> 兼容路径），详见 2.1 P0-2；P1-4 MaxHeaderBytes 维持 Go 默认 1MB 不收紧，仅暴露 Option，详见 2.1 P1-4 <strong>2026-08-23 拍板修订</strong>：P0-2 最终形态回调为「宽松保旧名 + 严格加新名」——<code>GetTime</code> 背离 <code>GetInt/GetStr</code> 宽松家族语义且迫使全部存量代码迁移；<code>ToTime/GetTime/GetTimeDefault</code> 恢复原签名，严格版为 <code>ToTimeE/GetTimeE</code>（即最初的方案 A，生成 base.go 与旧代码零改动） <strong>对照基准</strong>：Java 版 <code>/Users/airhead/WorkSpace/aifei/aifei</code>（dev 分支，HEAD=b25c056，2026-08-22 rebase）vs Go 版 <code>/Users/airhead/WorkSpace/aifei/aifei-go</code>（master，dcdb1a5） <strong>移植基线</strong>：aifei-go 核心移植完成于 2026-06-25；本文评估此后的 Java 变更（约 110 个提交，其间发布 v1.0.4 2026-07-17、v1.1.0 2026-08-17，后续至 08-20） <strong>范围</strong>：aifei core、aifei-db、aifei-enjoy、aifei-proxy、aifei-undertow。<strong>排除</strong>：新模块 <code>aifei-json-snack4</code>、<code>aifei-feathttp</code>（不关注） <strong>方法</strong>：逐提交核对 Java 行为变更（git log/show/diff + 当前源码）+ 盘点 Go 对应实现现状；文中行号基于各自当前 HEAD，审核时如有漂移以符号名为准</p></blockquote><hr><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h2><p><strong>核心判断</strong>：Java 版这轮演进的重心是<strong>数据正确性</strong>（类型映射、时间语义、事务硬化），不是新功能。Go 侧大部分改动因语言/范式差异天然免疫（Go 只有 <code>time.Time</code>、事务走 context、无代理机制），<strong>真正需要跟进的集中在 8 项</strong>，其中 2 项是 Go 侧真实存在的 bug/数据风险：</p><table tabindex="0"><thead><tr><th>类别</th><th>数量</th><th>代表</th></tr></thead><tbody><tr><td>需要实现</td><td>8（P0×2 / P1×4 / P2×2）</td><td>连接池线程安全、时间列读取</td></tr><tr><td>已天然覆盖</td><td>5</td><td>rollbackOnly、事务传播、启动失败退出、Byte/Short 折叠</td></tr><tr><td>不适用（语言/生态差异）</td><td>6</td><td>LocalDate 拆分、AOP 异常契约、代理缓存隔离等</td></tr></tbody></table><hr><h2 id="一、java-版演进归纳-2026-06-30-→-2026-08-22" tabindex="-1">一、Java 版演进归纳（2026-06-30 → 2026-08-22） <a class="header-anchor" href="#一、java-版演进归纳-2026-06-30-→-2026-08-22" aria-label="Permalink to &quot;一、Java 版演进归纳（2026-06-30 → 2026-08-22）&quot;">​</a></h2><h3 id="_1-1-jdbc-类型映射体系-07-12-08-19-最大主题" tabindex="-1">1.1 JDBC 类型映射体系（07-12 ~ 08-19，最大主题） <a class="header-anchor" href="#_1-1-jdbc-类型映射体系-07-12-08-19-最大主题" aria-label="Permalink to &quot;1.1 JDBC 类型映射体系（07-12 ~ 08-19，最大主题）&quot;">​</a></h3><p><code>TypeMapping</code> 拆成<strong>双表</strong>：</p><ol><li><code>classNameToJavaType</code> — 以 <code>ResultSetMetaData.getColumnClassName(i)</code> 返回的类名为键；</li><li><code>jdbcTypeToJavaType</code>（c894444 新增）— 以 <code>getColumnType(i)</code> 的 JDBC <code>Types</code> 常量为键的<strong>兜底表</strong>。</li></ol><p>07-12~13 的 6 个 &quot;complete JDBC type mappings&quot; 提交把两张表补到全 JDBC 覆盖；兜底默认值从 String 改为 <code>Object</code>。关键决策：</p><ul><li><code>REAL→Float</code>、<code>FLOAT→Double</code>（按 JDBC 4.2 附录 B，不能按直觉互换）；</li><li><code>TIMESTAMP_WITH_TIMEZONE</code>/<code>TIME_WITH_TIMEZONE</code> <strong>故意不设兜底</strong>（H2 老版本返回厂商类，兜底会生成运行时 ClassCastException 的 getter，宁可退到 Object）；</li><li><strong>Byte/Short → Integer 归一化</strong>（02131c7/7ac1baa）：跨驱动保持生成模型稳定；顺带删除 <code>AifeiRow.getByte()</code>/<code>queryByte()</code> 运行时 API；</li><li><strong>方言特化</strong>：Oracle NUMBER 按 scale/precision 收窄（scale==0 且 precision 1..9→Integer、10..18→Long、precision≤0 或负 scale 视为未知<strong>不收窄</strong>，889f05e）；SQLite 浮点一律 Double（5c8888b）。</li></ul><p>制度化原则：<strong>生成类型必须与 Dialect 运行时读取路径一致</strong> —— <code>Dialect.resolveColumnValueClassName()</code>（generator 侧推断）与 <code>readColumnValue()</code>（运行时读取）成对方言钩子（97a1fde→c78255d）。</p><h3 id="_1-2-列值读取-dialect-化-07-13-08-17" tabindex="-1">1.2 列值读取 Dialect 化（07-13 ~ 08-17） <a class="header-anchor" href="#_1-2-列值读取-dialect-化-07-13-08-17" aria-label="Permalink to &quot;1.2 列值读取 Dialect 化（07-13 ~ 08-17）&quot;">​</a></h3><p>列值读取从 RowFactory 移入 <code>Dialect.readColumnValue(ResultSet, int, int)</code>，按方言可覆盖：</p><ul><li>默认实现：<strong>DATE→<code>getDate()</code>、TIMESTAMP→<code>getTimestamp()</code></strong> 类型化读取（统一各驱动返回类型），其余 <code>getObject</code> + LOB 物化（仅当实际返回 Blob/Clob 对象；空 LOB→空数组、超 <code>Integer.MAX_VALUE</code> 抛异常、循环读满防短读）；</li><li>SqliteDialect：仅 BOOLEAN→<code>getBoolean()</code>+<code>wasNull()</code> 区分 false/null；</li><li>方向曾两次回调（e6608be 全 getObject → b41147e 移入 Dialect → 39d55c8 恢复类型化读取），最终语义是「类型化读取保证返回类型稳定，生成器按同一路径推断类型」。</li></ul><p><strong>08-18/19 的 BREAKING</strong>：<code>java.sql.Date</code>→<code>java.time.LocalDate</code>（262bfb3）、<code>java.sql.Time</code>→<code>java.time.LocalTime</code>（7ec1958），配套 <code>getLocalDate()/getLocalTime()</code> 等 API。</p><h3 id="_1-3-时间解析与转换硬化-07-19-07-22-横跨-enjoy-db-core-三模块" tabindex="-1">1.3 时间解析与转换硬化（07-19 ~ 07-22，横跨 enjoy/db/core 三模块） <a class="header-anchor" href="#_1-3-时间解析与转换硬化-07-19-07-22-横跨-enjoy-db-core-三模块" aria-label="Permalink to &quot;1.3 时间解析与转换硬化（07-19 ~ 07-22，横跨 enjoy/db/core 三模块）&quot;">​</a></h3><p>一套统一规则：<strong>宽度宽松、取值严格、整串消费、毫秒恰 3 位</strong>。</p><ul><li><code>TimeUtil</code>（enjoy）：<code>DateTimeFormatterBuilder</code> + <code>parseLenient()</code>（数字宽度可变，<code>&quot;2026-1-2 3:4:5&quot;</code> 可解析）+ <code>parseDefaulting(ERA/HOUR_OF_DAY)</code>（date-only 串解析为当天零点）+ <code>ResolverStyle.STRICT</code>（拒绝 <code>&quot;2020-2-30&quot;</code>）；<code>SimpleDateFormat</code> 一律 <code>setLenient(false)</code>；<code>parse</code> 用 <code>ParsePosition</code> 校验<strong>整串消费</strong>（拒绝尾部垃圾）；自动探测 pattern 时毫秒必须<strong>恰好 3 位</strong>；</li><li><code>TypeConverter</code>（db）：字符串解析全部委托 TimeUtil；类型间转换<strong>不隐式补日期/时间、不丢时区</strong> —— <code>toLocalTime(sql.Date)</code>/<code>toLocalDate(sql.Time)</code> 等缺半边的转换直接抛 IAE，<code>OffsetDateTime</code>→Timestamp 走 <code>toInstant()</code> 不丢 offset，<code>LocalDateTime</code>→Timestamp 按本地字段语义不走系统时区；</li><li><code>toBoolean</code> 先判 <code>Number</code>（1/0）再判 <code>String</code>，其它抛 IAE（828ce12）；</li><li>core 的 action 参数注入（<code>BasicArguments</code>）新增 <code>TemporalPattern</code> 枚举，同规则探测格式。</li></ul><p>SQL 参数绑定路径<strong>不做</strong>字符串日期解析（String 原样 <code>setObject</code>）；硬化影响的是值转换三处：Row/Kv/getter 转换、action 参数注入、enjoy 模板时间函数。</p><h3 id="_1-4-事务体系硬化-07-27-08-06" tabindex="-1">1.4 事务体系硬化（07-27 ~ 08-06） <a class="header-anchor" href="#_1-4-事务体系硬化-07-27-08-06" aria-label="Permalink to &quot;1.4 事务体系硬化（07-27 ~ 08-06）&quot;">​</a></h3><ul><li><strong>6 状态状态机</strong>（4335c40）替代三个布尔：<code>NEW→ACTIVE→COMMITTING/ROLLING_BACK→COMMITTED/ROLLED_BACK</code>；<code>rollbackOnly</code> 与状态<strong>正交</strong>（单向标记，置位后事务仍可操作但永久失去提交资格）；</li><li>begin 失败不残留 ThreadLocal（<code>setTransaction</code> 移到 begin 之后）、原始值用包装类型 null 判断（半途失败不恢复未读取的值）、<code>catch (Error)</code> 也回滚但原样抛出（1bea27e）；</li><li><code>onCommitSuccess</code> 回调<strong>延迟到连接恢复/close/ThreadLocal 清理之后</strong>执行（6335823，回调里的 DB 操作不再误用已提交事务的连接）；</li><li><strong>onException 回调守卫</strong>（808671d）：begin 失败不执行回调；回调执行期间禁止 <code>tx.getConnection()</code>/同 DbConfig 再开事务；</li><li><strong>删除 <code>Isolation.NONE</code></strong>（801b85f，无事务语义与隐式提交设计矛盾）；</li><li><strong>Transactional 拦截器注入 <code>Transaction</code> 参数</strong>（14eb9e2/8e2399c）：ThreadLocal 暴露当前事务 + <code>TransactionArgument</code> 参数注入；嵌套 Transactional 保存/恢复外层事务；<code>Db.transaction</code> 返回值（含异常回调兜底值）显式写回 Invocation。</li></ul><h3 id="_1-5-aifei-核心生命周期-07-31-08-16" tabindex="-1">1.5 Aifei 核心生命周期（07-31 ~ 08-16） <a class="header-anchor" href="#_1-5-aifei-核心生命周期-07-31-08-16" aria-label="Permalink to &quot;1.5 Aifei 核心生命周期（07-31 ~ 08-16）&quot;">​</a></h3><p>最终契约：启动路径任何 Throwable → 记日志 → <strong><code>System.exit(1)</code></strong>（非 daemon 线程会让失败进程假活）；关闭顺序 = server.stop → onStop 回调 → <strong>插件逆序停止</strong>；每步错误 <code>reportError</code> 吞掉并<strong>继续</strong>；<code>volatile started</code> 标志（start 重入抛 ISE、stop 幂等）；命令行参数 <code>split(&quot;=&quot;, 2)</code> 支持 value 含 <code>=</code>。</p><h3 id="_1-6-db-连接池生命周期线程安全-08-16-b7e6bbb" tabindex="-1">1.6 db 连接池生命周期线程安全（08-16，b7e6bbb） <a class="header-anchor" href="#_1-6-db-连接池生命周期线程安全-08-16-b7e6bbb" aria-label="Permalink to &quot;1.6 db 连接池生命周期线程安全（08-16，b7e6bbb）&quot;">​</a></h3><p><code>AifeiDb.start()/stop()</code> 加 synchronized + <code>started</code> 守卫；修复「未 start 过的实例 stop 会误删同 id 另一实例配置」；Druid/Hikari 供应商 get() 改双检锁语义。</p><h3 id="_1-7-其他" tabindex="-1">1.7 其他 <a class="header-anchor" href="#_1-7-其他" aria-label="Permalink to &quot;1.7 其他&quot;">​</a></h3><ul><li><code>undertow.maxHeaderSize</code> 配置，<strong>默认 16KB</strong>（794d6aa，收紧 Undertow 默认 1MB）；</li><li>PropKit active profiles 向<strong>所有</strong> <code>use()</code> 调用传播，system property 每次优先（4d79119）；</li><li><code>Operator.from()</code>→<code>of()</code> 改名（8a787d7）；</li><li>依赖升级：Undertow 2.2.40.Final、log4j2、fastjson2 2.0.63、javassist。</li></ul><hr><h2 id="二、go-侧差距评估" tabindex="-1">二、Go 侧差距评估 <a class="header-anchor" href="#二、go-侧差距评估" aria-label="Permalink to &quot;二、Go 侧差距评估&quot;">​</a></h2><h3 id="_2-1-需要实现-按优先级" tabindex="-1">2.1 需要实现（按优先级） <a class="header-anchor" href="#_2-1-需要实现-按优先级" aria-label="Permalink to &quot;2.1 需要实现（按优先级）&quot;">​</a></h3><h4 id="🔴-p0-1-db-config-连接池线程安全" tabindex="-1">🔴 P0-1：db.Config 连接池线程安全 <a class="header-anchor" href="#🔴-p0-1-db-config-连接池线程安全" aria-label="Permalink to &quot;🔴 P0-1：db.Config 连接池线程安全&quot;">​</a></h4><ul><li><strong>Go 现状</strong>：<code>db/config.go</code> — <code>configs</code> map（约 :85）读写<strong>无互斥</strong>；<code>Pool()</code>（:120-142）是 check-then-act 懒初始化，并发首次调用存在 data race（可能重复 <code>sql.Open</code>/<code>Ping</code> 泄漏连接）；<code>Close()</code>（:166-171）、<code>ResetConfigs()</code>（:174-179）同样无锁。</li><li><strong>Java 对应</strong>：b7e6bbb，真实 bug 级别（含「stop 误删他人配置」这类 Go 侧 <code>ResetConfigs</code> 同样存在的模式）。</li><li><strong>建议</strong>：<code>sync.RWMutex</code> 保护 configs map；<code>Pool()</code> 用 <code>sync.Once</code> 或 mutex 内双检；<code>InitWithID</code>/<code>GetConfig</code>/<code>Close</code>/<code>ResetConfigs</code> 全部走锁。</li></ul><h4 id="🔴-p0-2-时间列类型化读取-解析失败不静默" tabindex="-1">🔴 P0-2：时间列类型化读取 + 解析失败不静默 <a class="header-anchor" href="#🔴-p0-2-时间列类型化读取-解析失败不静默" aria-label="Permalink to &quot;🔴 P0-2：时间列类型化读取 + 解析失败不静默&quot;">​</a></h4><ul><li><strong>Go 现状</strong>：<code>db/executor.go</code> <code>scanRows</code>（:1116-1152）与 <code>execForEach</code>（:732-814）每列扫进 <code>interface{}</code> 后只做二分：<code>isBinaryColumnType</code>（:1231-1239）保留 <code>[]byte</code>，<strong>其余全部 <code>bytesToStr</code> 转 string</strong>。DATE/TIME/TIMESTAMP 无任何专门映射，Row 中时间列类型完全由驱动决定（MySQL 未开 <code>parseTime</code> 即 string）；<code>Row.GetTime</code>（<code>db/row.go:328</code>）→ <code>ToTime</code>（<code>db/type_converter.go:144-165</code>）按 5 种 layout 依次试错，<strong>全部失败静默返回零值 <code>time.Time{}</code></strong> —— 脏数据被吞掉。</li><li><strong>Java 对应</strong>：1.2 节整套（类型化读取 + <code>resolveColumnValueClassName</code> 一致性原则）。</li><li><strong>建议</strong>： <ol><li>scan 到 <code>interface{}</code> 后<strong>保留 <code>time.Time</code> 原生值</strong>（多数驱动已返回），<code>[]byte</code>/string 仅在列非时间型时转换；判断依据用 <code>columnType.DatabaseTypeName()</code>（与 <code>isBinaryColumnType</code> 同一模式，可加 <code>isTemporalColumnType</code>）；</li><li><strong>（已拍板 2026-08-23：方案 B，放弃 <code>ToTimeE</code> 兼容路径）</strong> <code>ToTime</code>/<code>GetTime</code> 改签名返回 <code>(time.Time, error)</code>： <ul><li>字符串解析失败 → 返回明确 error（含原始值与已尝试的 layout 提示），<strong>零值静默消除</strong>；</li><li><code>nil</code>（列 NULL）→ <code>(time.Time{}, nil)</code>：NULL 是缺值不是错误，与解析失败严格区分；</li><li><code>GetTimeDefault(field, def)</code> 语义调整为：NULL/缺失 → 默认值；解析失败 → error（默认值只兜 NULL，不兜脏数据）；</li><li>库内调用点同步适配：<code>json_codec.go</code> 的 <code>parseTimeValue</code>（JSON 输入路径）、<code>Row.GetTime</code> 之外的一切 <code>ToTime</code> 使用处；</li><li>v0.x 阶段允许破坏性变更，随 minor 标签发布；<code>_test/db_test</code> 补正反用例（合法格式、NULL、脏数据三类）；</li></ul></li><li>文档注明 MySQL DSN 需 <code>parseTime=true</code>（可在 <code>db.Init</code> 帮助层校验/提示）。</li></ol></li></ul><h4 id="🟡-p1-1-事务隔离级别支持" tabindex="-1">🟡 P1-1：事务隔离级别支持 <a class="header-anchor" href="#🟡-p1-1-事务隔离级别支持" aria-label="Permalink to &quot;🟡 P1-1：事务隔离级别支持&quot;">​</a></h4><ul><li><strong>Go 现状</strong>：<code>TransactionCtx</code>（<code>db/transaction.go:37-65</code>）用无参 <code>pool.Begin()</code>，<strong>无 <code>TxOptions</code></strong>，全库 grep 无 IsolationLevel；<code>tx.Rollback()</code> 返回值被<strong>静默忽略</strong>。</li><li><strong>Java 对应</strong>：1.4 节（Java 支持隔离级别且嵌套只升不降；删除 NONE）。</li><li><strong>建议</strong>：加 <code>TransactionOpts</code> 变体（<code>BeginTx(ctx, &amp;sql.TxOptions{Isolation: ...})</code>）；rollback 错误至少 <code>log</code> 记录（不覆盖原始错误）。Go 的 <code>sql.IsolationLevel</code> 无 NONE 语义问题，天然无需处理。</li></ul><h4 id="🟡-p1-2-插件逆序-stop" tabindex="-1">🟡 P1-2：插件逆序 Stop <a class="header-anchor" href="#🟡-p1-2-插件逆序-stop" aria-label="Permalink to &quot;🟡 P1-2：插件逆序 Stop&quot;">​</a></h4><ul><li><strong>Go 现状</strong>：<code>server/run.go</code>（约 :110）插件<strong>正序</strong> <code>p.Stop()</code>；错误已忽略不中断（<code>_ =</code>，与 Java 「遇错继续」一致 ✅）。</li><li><strong>建议</strong>：改逆序循环，一行改动。<code>started</code> 幂等标志对 Go 的一次性 <code>Run</code> 流程意义不大，可不做。</li></ul><h4 id="🟡-p1-3-config-扩展配置的-env-传播" tabindex="-1">🟡 P1-3：config 扩展配置的 env 传播 <a class="header-anchor" href="#🟡-p1-3-config-扩展配置的-env-传播" aria-label="Permalink to &quot;🟡 P1-3：config 扩展配置的 env 传播&quot;">​</a></h4><ul><li><strong>Go 现状</strong>：<code>app-{env}.yml</code> 只对 L1 base 文件生效（<code>config/config.go:156-169</code>）；L2 扩展配置（<code>config.include</code>，<code>collectExtensionPaths</code> :255-281）<strong>只按 glob 加载，没有 env 变体机制</strong> —— 即子配置加载时 env 不传播。</li><li><strong>Java 对应</strong>：4d79119（所有 <code>PropKit.use</code> 都追加 <code>file-{profile}.ext</code>）。</li><li><strong>建议</strong>：<code>collectExtensionPaths</code> 收集到的每个文件，同样尝试 <code>{base}-{env}.yml</code> 变体（存在则追加，env 变体优先级高于 base）。</li></ul><h4 id="🟡-p1-4-maxheaderbytes-配置" tabindex="-1">🟡 P1-4：MaxHeaderBytes 配置 <a class="header-anchor" href="#🟡-p1-4-maxheaderbytes-配置" aria-label="Permalink to &quot;🟡 P1-4：MaxHeaderBytes 配置&quot;">​</a></h4><ul><li><strong>Go 现状</strong>：<code>http/server.go:28-34</code> 构造 <code>&amp;http.Server{Addr, Handler}</code>，未设置 <code>MaxHeaderBytes</code>（Go 默认 1MB）也无配置暴露。</li><li><strong>Java 对应</strong>：794d6aa（默认收紧 16KB）。</li><li><strong>建议</strong>（已拍板 2026-08-23）：默认<strong>维持 Go 默认 1MB</strong>（不设置 <code>MaxHeaderBytes</code>，不对齐 Java 的 16KB——大 cookie/session 场景有破坏风险，Go 生态习惯显式收紧）；新增 <code>server.WithMaxHeaderBytes(n)</code> Option，穿透到 <code>http.Server.MaxHeaderBytes</code>；demo/文档示例中演示收紧到 16KB 的用法。</li></ul><h4 id="🟢-p2-1-tobool-补类型分支" tabindex="-1">🟢 P2-1：ToBool 补类型分支 <a class="header-anchor" href="#🟢-p2-1-tobool-补类型分支" aria-label="Permalink to &quot;🟢 P2-1：ToBool 补类型分支&quot;">​</a></h4><ul><li><strong>Go 现状</strong>：<code>db/type_converter.go:102-119</code> 覆盖 bool/int/int64/float64/string；int8/int16/int32/uint 及各无符号整型落入 default 返回 false；字符串仅认 <code>&quot;true&quot;/&quot;1&quot;/&quot;yes&quot;</code> 大小写有限集合。</li><li><strong>建议</strong>：default 分支用反射或显式列举补全整数族；字符串解析用 <code>strconv.ParseBool</code> + 现有集合。</li></ul><h4 id="🟢-p2-2-generator-分层兜底映射" tabindex="-1">🟢 P2-2：generator 分层兜底映射 <a class="header-anchor" href="#🟢-p2-2-generator-分层兜底映射" aria-label="Permalink to &quot;🟢 P2-2：generator 分层兜底映射&quot;">​</a></h4><ul><li><strong>Go 现状</strong>：<code>tools/generator/type_mapping.go</code> 单层 37 条 map，<code>GetType</code>（:68-73）未命中<strong>一律返回 string</strong>；<code>meta_reader.go:283/:322</code> 两个调用点（information_schema 路径与驱动反射 fallback 路径）无归一化层 —— PG 的 <code>timestamp with time zone</code> 这类带空格类型名直接落到 string。</li><li><strong>Java 对应</strong>：1.1 节双表 + 方言钩子。</li><li><strong>建议</strong>：不必照搬 JDBC 双表（Go 的 <code>ColumnType.DatabaseTypeName()</code> 已是驱动归一后的名字）；值得做的是①<code>NormalizeDataType</code> 归一化别名（剥长度后缀、<code>character varying</code>→<code>VARCHAR</code> 等）；②未命中默认值改为按 <code>ScanType</code> 推断或保持 string 但 log 提示。</li></ul><h3 id="_2-2-已天然覆盖-无需跟进" tabindex="-1">2.2 已天然覆盖 / 无需跟进 <a class="header-anchor" href="#_2-2-已天然覆盖-无需跟进" aria-label="Permalink to &quot;2.2 已天然覆盖 / 无需跟进&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Java 变更</th><th>Go 侧结论</th></tr></thead><tbody><tr><td>DATE→LocalDate / TIME→LocalTime（BREAKING）</td><td><strong>无需跟进</strong>：Go 只有 <code>time.Time</code> 一个时间类型，Java 拆三个类型的动机（字段语义/时区陷阱）在 Go 不存在；映射表 DATE/TIME/TIMESTAMP→<code>time.Time</code> 已是对等答案</td></tr><tr><td>rollbackOnly 状态机</td><td><strong>语义已覆盖</strong>：<code>Tx</code> 句柄主动 <code>Rollback()</code> 打标（<code>db/transaction.go:102-108</code>）+ <code>RollbackDecision</code>（:90-92）+ <code>ErrRollback</code> 哨兵（:97），<code>runAtomDecision</code>（:182-195）判定 fn 出错/打标/<code>ShouldRollback()</code> 三条件</td></tr><tr><td>Transactional 参数注入 + 嵌套恢复</td><td><strong>范式等价</strong>：Go 无法注入方法参数，<code>server.TxInterceptor</code>（<code>tx_interceptor.go:25-44</code>）经 <code>ctxSetter</code> 把携带 tx 的 ctx 塞回 Input，方法内 <code>db.Ctx(in.Context())</code> 加入事务；嵌套恢复 ctx 天然正确（子 ctx 不影响父）</td></tr><tr><td>onCommitSuccess 延迟 / onException 回调守卫</td><td><strong>不适用</strong>：Go 事务无回调机制</td></tr><tr><td>AOP 异常契约收窄（Exception）、反射拆包</td><td><strong>不适用</strong>：Go 无受检异常，<code>HandlerFunc</code> 返回 <code>Output</code>、panic 由 <code>server.Recover()</code> 承担</td></tr><tr><td>代理拦截器缓存按目标类隔离（269bb97 修串类 bug）</td><td><strong>不适用</strong>：Go 无 CGLIB/Javassist；<code>server.Register</code> 反射天然按具体类型，无共享 Method 缓存问题</td></tr><tr><td>启动失败 terminate JVM</td><td><strong>已等价</strong>：<code>server.Run</code> 插件启动失败/serve 失败均 <code>log.Fatalf</code> 退出进程</td></tr><tr><td>Byte/Short→Integer 归一化</td><td><strong>已等价</strong>：映射表 TINYINT/SMALLINT/MEDIUMINT→<code>int</code> 天然折叠</td></tr><tr><td>PropKit profile 主流程</td><td><strong>已覆盖</strong>：<code>resolveEnv</code>（CLI→<code>&lt;PREFIX&gt;_ENV</code>/<code>_PROFILE</code>）+ L1 env 变体；差距仅 2.1 P1-3 那条扩展配置传播</td></tr><tr><td>Oracle NUMBER 收窄</td><td><strong>不适用</strong>：Go 无 Oracle dialect（<code>NewDialect</code> 未知驱动 fallback SQLite）</td></tr><tr><td>依赖升级（Undertow/log4j2/fastjson2/javassist）</td><td><strong>不适用</strong>：Go 零外部依赖</td></tr><tr><td><code>Operator.from</code>→<code>of</code></td><td>Go 侧无对应命名习惯，不跟</td></tr><tr><td>aifei-json-snack4 / aifei-feathttp 新模块</td><td><strong>排除</strong>（不关注）：Java 生态 JSON 实现/HTTP 服务器选型；Go 侧 <code>encoding/json</code> + <code>net/http</code></td></tr></tbody></table><hr><h2 id="三、建议落地顺序" tabindex="-1">三、建议落地顺序 <a class="header-anchor" href="#三、建议落地顺序" aria-label="Permalink to &quot;三、建议落地顺序&quot;">​</a></h2><ol><li><strong>P0-1 连接池加锁</strong> —— 改动小、真 bug，独立可测（<code>-race</code> 压测）；</li><li><strong>P0-2 时间列读取</strong> —— 数据正确性核心，涉及 <code>scanRows</code>/<code>ToTime</code> 两处 + <code>_test/db_test</code> 补用例；</li><li><strong>P1-2 逆序 Stop / P1-1 隔离级别 / P1-3 env 传播</strong> —— 各自十几行以内，按顺手程度排；</li><li><strong>P1-4 MaxHeaderBytes</strong> —— 已拍板：默认维持 1MB，新增 <code>WithMaxHeaderBytes</code> Option（demo 示例演示 16KB 收紧用法）；</li><li><strong>P2 两项</strong> —— 视真实需求。</li></ol><p>总量估计：P0+P1 合计约 300~400 行（含测试）。P0-2 已拍板采用方案 B，是全部跟进项中<strong>唯一的破坏性 API 变更</strong>（<code>ToTime</code>/<code>GetTime</code>/<code>GetTimeDefault</code> 返回值加 error）；v0.x 阶段可直接实施，随 minor 标签发布。</p><hr><h2 id="四、落地记录-2026-08-23-实施完成" tabindex="-1">四、落地记录（2026-08-23 实施完成） <a class="header-anchor" href="#四、落地记录-2026-08-23-实施完成" aria-label="Permalink to &quot;四、落地记录（2026-08-23 实施完成）&quot;">​</a></h2><p>全部 8 项已实现并测试通过：</p><table tabindex="0"><thead><tr><th>项</th><th>实现</th><th>主要改动</th><th>测试</th></tr></thead><tbody><tr><td>P0-1</td><td>✅</td><td><code>db/config.go</code>：<code>configsMu sync.RWMutex</code> 保护 registry；<code>Config.mu</code> 保护 pool/SqlKit 惰性初始化；<code>Pool()</code> 失败时关闭已打开的句柄</td><td><code>config_concurrent_test.go</code>（3 用例，<code>-race</code> 通过）</td></tr><tr><td>P0-2</td><td>✅</td><td><code>scanRows</code>/<code>execForEach</code> 对 DATE/TIME/DATETIME/TIMESTAMP 列 scan 时类型化（<code>temporalLayoutsFor</code>+<code>scanTemporal</code>），脏数据在查询处报错；<code>ToStr</code> 支持 time.Time；<strong>宽松 <code>ToTime/GetTime/GetTimeDefault</code> 保持原签名原语义</strong>（与 <code>ToInt/GetStr</code> 家族一致，旧代码与生成 base.go 零改动），新增严格版 <code>ToTimeE/GetTimeE</code> 返回 <code>(time.Time, error)</code></td><td><code>temporal_test.go</code>（5 用例：类型化 scan/JSON 格式稳定/NULL/脏数据报错+严格宽松双路径/ToTimeE 契约）</td></tr><tr><td>P1-1</td><td>✅</td><td><code>TxOption</code>（<code>WithIsolation</code>/<code>WithReadOnly</code>）变参挂在 4 个 Ctx 入口，经 <code>BeginTx</code> 下发；<code>rollbackTx</code> 统一 4 处回滚（失败 <code>log.Warn</code>，不掩盖原始错误）；db 模块新增内部依赖 log</td><td><code>tx_options_test.go</code>（2 用例：隔离级别提交/回滚路径 + 嵌套 join）</td></tr><tr><td>P1-2</td><td>✅</td><td><code>server/run.go</code> 插件 Stop 改逆序</td><td>既有 server_test 回归</td></tr><tr><td>P1-3</td><td>✅</td><td><code>config/config.go</code>：<code>loadExtensionWithEnv</code>/<code>loadEnvVariantsFor</code>——L2 扩展配置（含 glob）每个文件加载后追加 <code>-{env}</code> 变体；L3 迟到 env 也补挂扩展变体</td><td><code>ext_env_test.go</code>（3 用例：单文件/glob/迟到 env）</td></tr><tr><td>P1-4</td><td>✅</td><td><code>http.DefaultServer.MaxHeaderBytes</code> 字段 + <code>server.WithMaxHeaderBytes(n)</code> Option；默认 0=net/http 1MB；demo 演示 <code>16&lt;&lt;10</code></td><td>既有 server_test 回归</td></tr><tr><td>P2-1</td><td>✅</td><td><code>ToBool</code>：整数族/浮点族全类型（含 uint/无符号、<code>[]byte</code>），字符串 <code>strconv.ParseBool</code>+yes/y/on 大小写不敏感，Number 先于 String</td><td><code>type_converter_test.go</code>（~50 断言）</td></tr><tr><td>P2-2</td><td>✅</td><td><code>NormalizeDataType</code>（剥长度后缀、PG 拼写别名折叠、int2/4/8）；<code>TypeMapping.Lookup</code> 归一化查找；<code>AddMapping/RemoveMapping</code> 归一化键；映射表补 UUID/BYTEA/CLOB 等；驱动路径未命中按 <code>ScanType</code> 推断</td><td><code>type_normalize_test.go</code>（3 用例）</td></tr></tbody></table><p><strong>验证</strong>：CLAUDE.md 全量测试清单通过（唯一失败 <code>_test/flow_plugin_test</code> 为动手前 master 上既有问题，与本批改动无关——测试文件函数签名与 <code>flowplugin.PersistFunc</code> 不匹配）。demo 构建通过。</p><p><strong>行为变化摘要</strong>（发布时值得写进变更说明）：</p><ol><li>时间列 scan 即类型化 + 脏数据报错（原先静默 string/零值）；</li><li>新增严格时间访问器 <code>ToTimeE/GetTimeE</code>；<code>ToTime/GetTime/GetTimeDefault</code> 保持原签名原宽松语义（与 <code>ToInt/GetStr</code> 一致）。<strong>无破坏性 API 变更</strong>（v0.0.47 曾短暂将 <code>GetTime</code> 改严格双返回值并引入 <code>GetTimeOrZero</code>，v0.0.48 起恢复原名宽松语义、严格版改用 <code>E</code> 后缀，<code>GetTimeOrZero</code> 移除）；</li><li><code>AddMapping/RemoveMapping/GetType</code> 键经归一化（大小写/别名/后缀不敏感）；</li><li>db 模块新增内部依赖 <code>log</code>（仍零外部依赖）。</li></ol>',62)])])}const m=o(a,[["render",r]]);export{h as __pageData,m as default};
